insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$physiography$t$, $t$Physiography$t$, $t$প্ৰাকৃতিক গঠন$t$, $t$The natural shape of the land: its plains, hills, plateaus and valleys.$t$, $t$ভূমিৰ প্ৰাকৃতিক গঠন: ইয়াৰ সমভূমি, পাহাৰ, মালভূমি আৰু উপত্যকা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$valley$t$, $t$Valley$t$, $t$উপত্যকা$t$, $t$Low land between hills or mountains, usually with a river flowing through it.$t$, $t$পাহাৰ বা পৰ্বতৰ মাজৰ নিম্নভূমি, য'ৰ মাজেৰে সাধাৰণতে নদী বৈ যায়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$plateau$t$, $t$Plateau$t$, $t$মালভূমি$t$, $t$A raised area of land that is fairly flat on top.$t$, $t$ওপৰভাগ প্ৰায় সমান থকা ওখ ভূমি।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$tributary$t$, $t$Tributary$t$, $t$উপনৈ$t$, $t$A smaller river that flows into a bigger river.$t$, $t$ডাঙৰ নদীত আহি মিলি যোৱা সৰু নদী।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$braided-river$t$, $t$Braided river$t$, $t$বেণীবদ্ধ নদী$t$, $t$A river that splits into many channels around sandbanks and islands, like a braid of hair.$t$, $t$চাপৰি আৰু দ্বীপৰ চাৰিওফালে বহু সুঁতিত বিভক্ত হৈ চুলিৰ বেণীৰ দৰে বোৱা নদী।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$river-island$t$, $t$River island$t$, $t$নদী দ্বীপ$t$, $t$Land surrounded by the channels of a river. Majuli is the best-known river island of Assam.$t$, $t$নদীৰ সুঁতিৰে আগুৰা ভূমি। মাজুলী অসমৰ আটাইতকৈ জনাজাত নদী দ্বীপ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$confluence$t$, $t$Confluence$t$, $t$সংগম$t$, $t$The place where two or more rivers meet.$t$, $t$দুখন বা তাতোকৈ বেছি নদী মিলিত হোৱা ঠাই।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$monsoon$t$, $t$Monsoon$t$, $t$মৌচুমী$t$, $t$The season of strong rain-bearing winds. In Assam the monsoon rains are heaviest in summer.$t$, $t$বৰষুণ কঢ়িয়াই অনা প্ৰবল বতাহৰ ঋতু। অসমত গ্ৰীষ্মকালত মৌচুমী বৰষুণ আটাইতকৈ বেছি হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$bordoisila$t$, $t$Bordoisila$t$, $t$বৰদৈচিলা$t$, $t$The strong afternoon thunderstorms of the Bohag Bihu season (spring) in Assam.$t$, $t$অসমত বহাগ বিহুৰ সময়ত (বসন্তকালত) আবেলি হোৱা প্ৰবল ধুমুহা-বৰষুণ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$alluvial-soil$t$, $t$Alluvial soil$t$, $t$পলসুৱা মাটি$t$, $t$Fertile soil made of silt and sand laid down by rivers, especially after floods.$t$, $t$নদীয়ে বিশেষকৈ বানপানীৰ পিছত পেলাই থৈ যোৱা পলস আৰু বালিৰে গঠিত উৰ্বৰ মাটি।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$tertiary-coal$t$, $t$Tertiary coal$t$, $t$টাৰ্চিয়াৰী কয়লা$t$, $t$Younger coal formed in the Tertiary period of the earth's history. Assam's coal is of this kind.$t$, $t$পৃথিৱীৰ ইতিহাসৰ টাৰ্চিয়াৰী যুগত গঠন হোৱা তুলনামূলকভাৱে নতুন কয়লা। অসমৰ কয়লা এই প্ৰকাৰৰ।$t$) on conflict (slug) do nothing;
insert into public.content (slug, kind, category_id, position) select $t$physical-divisions-of-assam$t$, 'gk_chapter', id, 1 from public.categories where slug = $t$geography$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Physical divisions of Assam$t$, $t$The Brahmaputra Valley, the Barak Valley and the hills of Karbi Anglong and Dima Hasao.$t$, 'draft', $t$Geography of Assam, Wikipedia: https://en.wikipedia.org/wiki/Geography_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$By its {{term:physiography}}, Assam can be divided into three parts:$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'geography', $t$The Brahmaputra Valley: about 80 to 100 km wide and almost 1,000 km long. It covers most of the state.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$The Karbi Anglong hills are part of the Deccan {{term:plateau}}, which shows how old this land is.$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$Assam lies in a zone of strong earthquakes. The great earthquakes of 1897 and 1950 measured 8.3 and 8.6 in magnitude.$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: three divisions: Brahmaputra Valley, Barak Valley, and the Karbi Anglong and Dima Hasao hills. Earthquakes of 1897 (8.3) and 1950 (8.6).$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ প্ৰাকৃতিক বিভাগ$t$, $t$ব্ৰহ্মপুত্ৰ উপত্যকা, বৰাক উপত্যকা আৰু কাৰ্বি আংলং আৰু ডিমা হাছাওৰ পাহাৰ।$t$, 'draft', $t$Geography of Assam, Wikipedia: https://en.wikipedia.org/wiki/Geography_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:physiography|প্ৰাকৃতিক গঠন}} অনুসৰি অসমক তিনিটা ভাগত ভগাব পাৰি:$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'geography', $t$ব্ৰহ্মপুত্ৰ উপত্যকা: প্ৰায় ৮০ ৰ পৰা ১০০ কিমি বহল আৰু প্ৰায় ১,০০০ কিমি দীঘল। ৰাজ্যখনৰ বেছিভাগ অংশ ইয়াৰ ভিতৰত পৰে।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$কাৰ্বি আংলঙৰ পাহাৰবোৰ দাক্ষিণাত্য {{term:plateau|মালভূমিৰ}} অংশ, যিয়ে এই ভূমিৰ প্ৰাচীনত্ব দেখুৱায়।$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'normal', $t$অসম প্ৰবল ভূমিকম্পৰ অঞ্চলত অৱস্থিত। ১৮৯৭ আৰু ১৯৫০ চনৰ বৰ ভূমিকম্পৰ মাত্ৰা আছিল ক্ৰমে ৮.৩ আৰু ৮.৬।$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: তিনিটা বিভাগ: ব্ৰহ্মপুত্ৰ উপত্যকা, বৰাক উপত্যকা, আৰু কাৰ্বি আংলং আৰু ডিমা হাছাওৰ পাহাৰ। ১৮৯৭ (৮.৩) আৰু ১৯৫০ (৮.৬) চনৰ ভূমিকম্প।$t$ from public.content where slug = $t$physical-divisions-of-assam$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$brahmaputra-river-system$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$geography$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The Brahmaputra river system$t$, $t$Where the Brahmaputra comes from, its names, its tributaries in Assam, and Majuli.$t$, 'draft', $t$Brahmaputra River, Wikipedia: https://en.wikipedia.org/wiki/Brahmaputra_River$t$, date '2026-11-24' from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Brahmaputra rises in Tibet, in the region of Lake Manasarovar. It is about 3,000 km long, though different sources give figures between 2,880 and 3,080 km.$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'geography', $t$In Tibet: Yarlung Tsangpo
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$Just west of Sadiya, the Dihang is joined by the Lohit and the Dibang. Below this {{term:confluence}} the river is called the Brahmaputra. It then flows about 700 km through Assam as a wide {{term:braided-river|braided river}}.$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 4, 'heading', 'normal', $t$Main tributaries in Assam$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l2', 5, 'list', 'geography', $t$From the north (Himalayan side): Subansiri, Kameng (Jia Bharali), Dhansiri, Manas, Champamati, Saralbhanga and Sankosh
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 6, 'paragraph', 'normal', $t$Each of these is a {{term:tributary}} of the Brahmaputra. Between Dibrugarh and Lakhimpur the river splits into two channels that join again about 100 km downstream, forming Majuli, often called the largest {{term:river-island|river island}} in the world.$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$In Bangladesh the Jamuna joins the Ganga, and the combined river, the Padma, later meets the Meghna and flows into the Bay of Bengal.$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Tsangpo (Tibet), Siang/Dihang (Arunachal), Brahmaputra (Assam), Jamuna (Bangladesh). Dihang, Lohit and Dibang meet near Sadiya.$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$ব্ৰহ্মপুত্ৰ নদী প্ৰণালী$t$, $t$ব্ৰহ্মপুত্ৰৰ উৎস, ইয়াৰ বিভিন্ন নাম, অসমত ইয়াৰ উপনৈসমূহ আৰু মাজুলী।$t$, 'draft', $t$Brahmaputra River, Wikipedia: https://en.wikipedia.org/wiki/Brahmaputra_River$t$, date '2026-11-24' from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$ব্ৰহ্মপুত্ৰৰ উৎপত্তি তিব্বতৰ মানসৰোবৰ হ্ৰদৰ অঞ্চলত। ইয়াৰ দৈৰ্ঘ্য প্ৰায় ৩,০০০ কিমি, যদিও বিভিন্ন উৎসত ২,৮৮০ ৰ পৰা ৩,০৮০ কিমিৰ ভিতৰৰ বেলেগ বেলেগ হিচাপ পোৱা যায়।$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'geography', $t$তিব্বতত: ইয়াৰলুং চাংপো
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$শদিয়াৰ ঠিক পশ্চিমে ডিহাঙৰ সৈতে লুইত আৰু দিবাং মিলিত হয়। এই {{term:confluence|সংগমৰ}} তলৰ পৰা নদীখনক ব্ৰহ্মপুত্ৰ বোলা হয়। তাৰ পিছত ই এখন বহল {{term:braided-river|বেণীবদ্ধ নদী}} হিচাপে অসমৰ মাজেৰে প্ৰায় ৭০০ কিমি বৈ যায়।$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 4, 'heading', 'normal', $t$অসমত মূল উপনৈসমূহ$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l2', 5, 'list', 'geography', $t$উত্তৰৰ পৰা (হিমালয়ৰ ফালৰ): সোৱণশিৰি, কামেং (জীয়াভৰলী), ধনশিৰি, মানাহ, চম্পাৱতী, সৰলভাংগা আৰু সংকোষ
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 6, 'paragraph', 'normal', $t$এইবোৰ প্ৰতিখনেই ব্ৰহ্মপুত্ৰৰ {{term:tributary|উপনৈ}}। ডিব্ৰুগড় আৰু লখিমপুৰৰ মাজত নদীখন দুটা সুঁতিত ভাগ হৈ প্ৰায় ১০০ কিমি তলত পুনৰ লগ লাগে আৰু মাজুলীৰ সৃষ্টি কৰে, যাক প্ৰায়ে পৃথিৱীৰ বৃহত্তম {{term:river-island|নদী দ্বীপ}} বুলি কোৱা হয়।$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$বাংলাদেশত যমুনা গংগাৰ সৈতে মিলিত হয়, আৰু এই মিলিত নদী পদ্মাই পিছত মেঘনাৰ সৈতে লগ লাগি বংগোপসাগৰত পৰে।$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: চাংপো (তিব্বত), চিয়াং/ডিহাং (অৰুণাচল), ব্ৰহ্মপুত্ৰ (অসম), যমুনা (বাংলাদেশ)। ডিহাং, লুইত আৰু দিবাং শদিয়াৰ ওচৰত মিলিত হয়।$t$ from public.content where slug = $t$brahmaputra-river-system$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$barak-river-system$t$, 'gk_chapter', id, 3 from public.categories where slug = $t$geography$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The Barak river system$t$, $t$The Barak river, its course through southern Assam and its tributaries.$t$, 'draft', $t$Barak River, Wikipedia: https://en.wikipedia.org/wiki/Barak_River$t$, date '2026-11-24' from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Barak is the main river of southern Assam. It rises near Liyai Khullen village in Senapati district, Manipur, at a height of about 987 metres.$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$From Manipur it flows to Tipaimukh, turns north to Jirimukh and then flows west into Cachar district of Assam, and on through Sribhumi (Karimganj) district.$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'normal', $t$It enters Bangladesh at Bhanga Bazar, where it splits into two rivers, the Surma and the Kushiyara. These later join to form the Meghna.$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 4, 'heading', 'normal', $t$Tributaries of the Barak$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 5, 'paragraph', 'geography', $t$Its main {{term:tributary|tributaries}} include the Jiri, Sonai, Dhaleswari, Jatinga, Longai and Madhura.$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 6, 'paragraph', 'normal', $t$The Barak is about 900 km long. Its basin covers about 52,000 sq km, of which 41,723 sq km is in India.$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: the Barak rises in Manipur and splits into the Surma and the Kushiyara in Bangladesh.$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$বৰাক নদী প্ৰণালী$t$, $t$বৰাক নদী, দক্ষিণ অসমৰ মাজেৰে ইয়াৰ গতিপথ আৰু ইয়াৰ উপনৈসমূহ।$t$, 'draft', $t$Barak River, Wikipedia: https://en.wikipedia.org/wiki/Barak_River$t$, date '2026-11-24' from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$বৰাক দক্ষিণ অসমৰ প্ৰধান নদী। ইয়াৰ উৎপত্তি মণিপুৰৰ চেনাপতি জিলাৰ লিয়াই খুলেন গাঁৱৰ ওচৰত, প্ৰায় ৯৮৭ মিটাৰ উচ্চতাত।$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$মণিপুৰৰ পৰা ই টিপাইমুখলৈ বৈ যায়, তাৰ পৰা উত্তৰে জিৰিমুখলৈ ঘূৰি পশ্চিমমুৱাকৈ অসমৰ কাছাৰ জিলাত সোমায়, আৰু শ্ৰীভূমি (কৰিমগঞ্জ) জিলাৰ মাজেৰে আগবাঢ়ে।$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'normal', $t$ভাঙা বজাৰত ই বাংলাদেশত প্ৰৱেশ কৰে আৰু তাত সুৰমা আৰু কুশিয়াৰা নামৰ দুখন নদীত বিভক্ত হয়। পিছত এই দুখন লগ লাগি মেঘনা হয়।$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 4, 'heading', 'normal', $t$বৰাকৰ উপনৈসমূহ$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 5, 'paragraph', 'geography', $t$ইয়াৰ মূল {{term:tributary|উপনৈসমূহৰ}} ভিতৰত আছে জিৰি, সোণাই, ধলেশ্বৰী, জাটিংগা, লংগাই আৰু মধুৰা।$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 6, 'paragraph', 'normal', $t$বৰাকৰ দৈৰ্ঘ্য প্ৰায় ৯০০ কিমি। ইয়াৰ অৱবাহিকাৰ আয়তন প্ৰায় ৫২,০০০ বৰ্গ কিমি, যাৰ ৪১,৭২৩ বৰ্গ কিমি ভাৰতত।$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: বৰাকৰ উৎপত্তি মণিপুৰত আৰু বাংলাদেশত ই সুৰমা আৰু কুশিয়াৰাত বিভক্ত হয়।$t$ from public.content where slug = $t$barak-river-system$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$climate-and-floods$t$, 'gk_chapter', id, 4 from public.categories where slug = $t$geography$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Climate and floods$t$, $t$Assam's seasons, monsoon rains, Bordoisila storms and the yearly floods.$t$, 'draft', $t$Geography of Assam, Wikipedia: https://en.wikipedia.org/wiki/Geography_of_Assam$t$, date '2026-11-24' from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam has a tropical {{term:monsoon}} climate, with heavy rain and high humidity.$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'geography', $t$Winter: from late October to late February. Nights are foggy, and the lowest temperature is about 6 to 8 °C.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Floods$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$Floods come almost every year in Assam. Heavy rainfall and the cutting of forests make them worse. They cause loss of life, homes, crops and livelihoods.$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$Floods also lay down fresh silt on the plains, which keeps the soil fertile.$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Assam's climate is tropical monsoon; Bordoisila is the spring thunderstorm.$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$জলবায়ু আৰু বানপানী$t$, $t$অসমৰ ঋতু, মৌচুমী বৰষুণ, বৰদৈচিলা আৰু বছৰেকীয়া বানপানী।$t$, 'draft', $t$Geography of Assam, Wikipedia: https://en.wikipedia.org/wiki/Geography_of_Assam$t$, date '2026-11-24' from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমৰ জলবায়ু ক্ৰান্তীয় {{term:monsoon|মৌচুমী}} প্ৰকৃতিৰ, য'ত প্ৰচুৰ বৰষুণ আৰু অধিক আৰ্দ্ৰতা থাকে।$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'geography', $t$শীতকাল: অক্টোবৰৰ শেষৰ পৰা ফেব্ৰুৱাৰীৰ শেষলৈ। ৰাতি কুঁৱলী পৰে আৰু সৰ্বনিম্ন উষ্ণতা প্ৰায় ৬ ৰ পৰা ৮ °C।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$বানপানী$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$অসমত প্ৰায় প্ৰতি বছৰে বানপানী হয়। অধিক বৰষুণ আৰু হাবি-বন নিধনে ইয়াক অধিক ভয়াবহ কৰে। ইয়াৰ ফলত প্ৰাণ, ঘৰ-দুৱাৰ, শস্য আৰু জীৱিকাৰ ক্ষতি হয়।$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$বানপানীয়ে সমভূমিত নতুন পলস পেলাই থৈ যায়, যিয়ে মাটি উৰ্বৰ কৰি ৰাখে।$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: অসমৰ জলবায়ু ক্ৰান্তীয় মৌচুমী; বৰদৈচিলা বসন্তকালৰ ধুমুহা।$t$ from public.content where slug = $t$climate-and-floods$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$soils-minerals-forests$t$, 'gk_chapter', id, 5 from public.categories where slug = $t$geography$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Soils, minerals and forests$t$, $t$Fertile river soils, oil, gas, coal and limestone, and where they are found.$t$, 'draft', $t$Geography of Assam, Wikipedia: https://en.wikipedia.org/wiki/Geography_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The plains of the Brahmaputra and Barak valleys have fertile {{term:alluvial-soil|alluvial soil}}, renewed by the rivers. This is why farming is the main occupation in Assam.$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Minerals$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 3, 'list', 'geography', $t$Petroleum and natural gas: found in the districts of Upper Assam. Petroleum was discovered in Assam in 1889.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 4, 'heading', 'normal', $t$Forests$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 5, 'paragraph', 'normal', $t$Assam has rich tropical forests. Kaziranga and Manas, two of its protected forests, are UNESCO World Heritage Sites.$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: petroleum found in Assam in 1889; coal belt of Upper Assam is Tertiary; limestone at Umrangso.$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$মাটি, খনিজ আৰু অৰণ্য$t$, $t$উৰ্বৰ পলসুৱা মাটি, তেল, গেছ, কয়লা আৰু চূণশিল, আৰু সেইবোৰ ক'ত পোৱা যায়।$t$, 'draft', $t$Geography of Assam, Wikipedia: https://en.wikipedia.org/wiki/Geography_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$ব্ৰহ্মপুত্ৰ আৰু বৰাক উপত্যকাৰ সমভূমিত নদীয়ে নৱীকৰণ কৰি ৰখা উৰ্বৰ {{term:alluvial-soil|পলসুৱা মাটি}} আছে। সেইবাবেই কৃষি অসমৰ মূল বৃত্তি।$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
