insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 3, 'list', 'geography', $t$খাৰুৱা তেল আৰু প্ৰাকৃতিক গেছ: উজনি অসমৰ জিলাসমূহত পোৱা যায়। ১৮৮৯ চনত অসমত খাৰুৱা তেল আৱিষ্কাৰ হয়।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 4, 'heading', 'normal', $t$অৰণ্য$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 5, 'paragraph', 'normal', $t$অসমত চহকী ক্ৰান্তীয় অৰণ্য আছে। ইয়াৰ দুখন সংৰক্ষিত বনাঞ্চল কাজিৰঙা আৰু মানাহ ইউনেস্কোৰ বিশ্ব ঐতিহ্য ক্ষেত্ৰ।$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ১৮৮৯ চনত অসমত খাৰুৱা তেল পোৱা যায়; উজনি অসমৰ কয়লা টাৰ্চিয়াৰী; উমৰাংছুত চূণশিল।$t$ from public.content where slug = $t$soils-minerals-forests$t$ on conflict do nothing;
